import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {useContext,useMemo as useIdentityMemo} from 'react';
import {EditorInteractionScope,useEditorBoundary} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useScopedControl,controlIdentity,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {timelineEditSignature} from '@/components/nyc-tron/ui/components/forge/timeline/timeline-identity';
/*
 * Original implementation for NYC-Tron UI; no third-party source. Provenance
 * is recorded in docs/COMPONENT_OWNERSHIP.md.
 */
import {Text,View,type ViewProps} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {Button} from "@/components/nyc-tron/ui/components/Button";
import {SegmentedControl} from "@/components/nyc-tron/ui/components/SegmentedControl";
import {rippleDeleteEdit,type MoveMode,type RippleScope,type TimelineEdit,type TimelineTrack} from "@/components/nyc-tron/ui/components/forge/timeline/edits";
import {TRIM_MODE_PROBLEM_TEXT,rippleDeletePreview} from "@/components/nyc-tron/ui/components/forge/timeline/trim-modes";
import {space} from '@/components/nyc-tron/ui/tokens';

/** Props for {@linkcode DragReorderAndRipple}. */
export interface DragReorderAndRippleProps extends Omit<ViewProps,"children">,ScopedControlProps {
  /** Pass the same value to `TimelineClipLane` `moveMode`. `undefined` is a strict move. */
  readonly moveMode:MoveMode|undefined;
  readonly onMoveModeChange:(mode:MoveMode|undefined)=>void;
  /** Pass the same value to `TimelineClipLane` `rippleScope`. */
  readonly rippleScope:RippleScope;
  readonly onRippleScopeChange:(scope:RippleScope)=>void;
  readonly tracks:readonly TimelineTrack[];
  readonly selectedClipId?:string;
  /** The ripple delete, once per press. */
  readonly onEdit:(edit:TimelineEdit)=>void;
  readonly disabled?:boolean;
  className?:string;
  unstyled?:boolean;
}

type ModeValue="strict"|MoveMode;
const MODES:readonly {value:ModeValue;label:string}[]=[
  {value:"strict",label:"No overlap"},{value:"overwrite",label:"Overwrite"},{value:"insert",label:"Insert"},
];
const MODE_HELP:Readonly<Record<ModeValue,string>>={
  strict:"A move that would cover another clip is refused.",
  overwrite:"A dropped clip replaces what it covers. Drag up or down to change track.",
  insert:"A dropped clip pushes later clips right. Drag up or down to change track.",
};

/**
 * Move and ripple settings (D-22): how a dragged clip lands on others
 * (refuse, overwrite, insert), which tracks a ripple shifts (this track or
 * every unlocked track), and Ripple delete for the selected clip, which
 * removes it and closes the gap as one edit. Ripple delete is disabled, with
 * the reason shown, when there is no selection, the track is locked, or
 * closing the gap would overlap a clip on another track.
 */
export function DragReorderAndRipple({scope='DragReorderAndRipple',revision=0,...props}:DragReorderAndRippleProps){
 const parent=useContext(EditorInteractionScope),owner=JSON.stringify(controlIdentity(scope,revision));
 const signature=useIdentityMemo(()=>timelineEditSignature(props.tracks),[props.tracks]);
 const boundary=useEditorBoundary([owner,parent,props.disabledReason,props.disabled,signature,props.selectedClipId,props.moveMode,props.rippleScope]);
 const guard=useScopedControl(boundary,props,props.disabledReason!==undefined||!!props.disabled);
 return <EditorInteractionScope.Provider value={boundary}><DragReorderAndRippleBody key={owner} {...props} actionError={guard.error} disabled={!!props.disabled||props.disabledReason!==undefined||guard.pending}
  onEdit={(value)=>guard.run('onEdit',host=>host.onEdit(value))}
  onMoveModeChange={(value)=>guard.current()?.onMoveModeChange(value)}
  onRippleScopeChange={(value)=>guard.current()?.onRippleScopeChange(value)}/></EditorInteractionScope.Provider>;
}
function DragReorderAndRippleBody({
 actionError=null,disabledReason,
  moveMode,onMoveModeChange,rippleScope,onRippleScopeChange,tracks,selectedClipId,onEdit,disabled=false,
  className,unstyled=false,testID,style,...rest
}:DragReorderAndRippleProps&{actionError?:string|null}){
  const styled=!unstyled;
  const id=(s:string)=>testID?{testID:testID+"-"+s}:{};
  const found=tracks.flatMap(t=>t.clips.filter(c=>c.id===selectedClipId).map(clip=>({track:t,clip})))[0];
  const preview=found?rippleDeletePreview(tracks,found.track,found.clip,rippleScope):undefined;
  const reason=!found?"Select a clip to ripple delete it":preview&&!preview.valid&&preview.problem?TRIM_MODE_PROBLEM_TEXT[preview.problem]:undefined;
  const mode:ModeValue=moveMode??"strict";
  return <View {...rest} {...(testID?{testID}:{})} {...{className:joinClasses("gap-2",className)}} style={style}>
    <ErrorMessage message={actionError??undefined} unstyled={unstyled}/>
    <SegmentedControl aria-label="When a moved clip meets another" options={MODES} value={mode} disabled={disabled}
      onChange={v=>onMoveModeChange(v==="strict"?undefined:v)} unstyled={unstyled} {...id("mode")}/>
    <Text {...{className:joinClasses(styled&&"text-text-muted text-xs")}}>{MODE_HELP[mode]}</Text>
    <View style={{flexDirection:"row",flexWrap:"wrap",alignItems:"center",gap:space[2]}}>
      <SegmentedControl aria-label="Ripple affects" value={rippleScope} onChange={onRippleScopeChange} disabled={disabled}
        options={[{value:"track",label:"This track"},{value:"all",label:"All tracks"}]} unstyled={unstyled} {...id("scope")}/>
      <Button title="Ripple delete" variant="secondary" size="sm" disabled={disabled||!found||!preview?.valid} {...id("ripple-delete")}
        accessibilityHint={reason??"Remove the selected clip and close the gap"}
        onPress={()=>{if(found&&preview?.valid)onEdit(rippleDeleteEdit(found.clip.id,found.track.id,rippleScope));}}/>
    </View>
    {reason&&!disabled?<Text {...id("reason")} {...{className:joinClasses(styled&&"text-text-muted text-xs")}}>{reason}.</Text>:null}
  </View>;
}

import type {TimelineTrack} from '@/components/nyc-tron/ui/components/forge/timeline/edits';
/** Bounded geometry/permission identity; a playback clock tick is not an edit. */
export function timelineEditSignature(tracks:readonly TimelineTrack[]):string{
 if(tracks.length>1000)throw new RangeError('Too many timeline tracks');
 const trackIds=new Set<string>(),clipIds=new Set<string>();let count=0;
 for(const track of tracks){
  if(!track.id.trim()||track.id.length>512||trackIds.has(track.id)||track.label.length>1024||!['video','overlay','audio'].includes(track.kind))throw new RangeError('Invalid timeline track');trackIds.add(track.id);
  count+=track.clips.length;if(count>50000)throw new RangeError('Too many timeline clips');
  for(const clip of track.clips){
   if(!clip.id.trim()||clip.id.length>512||clipIds.has(clip.id)||!Number.isSafeInteger(clip.startFrame)||clip.startFrame<0||![clip.sourceIn,clip.sourceOut,clip.speed].every(Number.isFinite)||clip.sourceIn<0||clip.sourceOut<=clip.sourceIn||clip.speed<=0||clip.sourceDuration!==undefined&&(!Number.isFinite(clip.sourceDuration)||clip.sourceDuration<clip.sourceOut))throw new RangeError('Invalid timeline clip');clipIds.add(clip.id);
  }
 }
 return JSON.stringify(tracks.map(t=>[t.id,t.kind,t.locked,t.hidden,t.muted,t.solo,t.clips.map(c=>[c.id,c.startFrame,c.sourceIn,c.sourceOut,c.speed,c.sourceDuration])]));
}

import {createContext,useRef} from 'react';
/** Invalidate ephemeral gestures without remounting focused controls or product state. */
export const EditorInteractionScope=createContext<string|null>(null);
let nextInstance=0;
/** Compare cached document signatures by identity without reserializing a whole
 * timeline on every playback tick or nesting its data in child scope strings. */
export function useEditorBoundary(parts:readonly unknown[]):string{
 const ref=useRef<{id:number;version:number;parts:readonly unknown[]}|null>(null);
 ref.current??={id:++nextInstance,version:0,parts:[]};
 const current=ref.current;
 if(parts.length!==current.parts.length||parts.some((part,index)=>!Object.is(part,current.parts[index]))){current.parts=[...parts];current.version++;}
 return current.id+':'+current.version;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

